mapper.select:
WITH amount_detail AS ( SELECT daily.expense_date, parent.id AS parent_id, parent.category_name AS parent_category, child.id child_id, child.category_name child_category, daily.expense_amount AS expenseTotal, daily.remark FROM base_tally_category parent LEFT JOIN base_tally_category child ON child.parent_id = parent.id OR parent.id = child.id JOIN daily_expense_record daily ON daily.category_id = child.id AND daily.expense_date BETWEEN #{startDate} AND #{endDate} AND daily.del_flag = 0 WHERE parent.parent_id = 0 AND parent.expense_type = 1 ORDER BY daily.expense_date, parent.id, child.id ) SELECT * FROM amount_detail WHERE 1 = 1
AND parent_id = #{bigCategoryId}
AND child_id = #{smallCategoryId}
ORDER BY expense_date DESC, parent_id, child_id
